import {SAVE_KEY,newState,normaliseState,chapterDone,unlocked,earnedXP,rank,completeInvestigation} from './state.js';
const $=s=>document.querySelector(s),app=$('#app'),panel=$('#panel'),content=$('#panel-content');
let course,campaign,state,flow=null,returnFocus=null,toastTimer,audioContext,searchQuery='';
const sceneLabels=['De belofte','Achter de schermen','Aan de bestuurstafel','De onzichtbare regels','Het verhaal naar buiten'];
const spots=[[[15,50],[43,72],[65,38],[84,62]],[[21,34],[45,48],[63,26],[84,65]],[[20,61],[59,73],[66,23],[84,34]],[[19,48],[45,58],[68,27],[91,42]],[[17,30],[43,77],[60,39],[85,35]]];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function html(s){const doc=new DOMParser().parseFromString(String(s??''),'text/html');doc.querySelectorAll('script,iframe,object,embed,link,style').forEach(e=>e.remove());doc.querySelectorAll('*').forEach(e=>{for(const a of [...e.attributes])if(a.name.startsWith('on')||(/^(href|src)$/i.test(a.name)&&/^\s*javascript:/i.test(a.value)))e.removeAttribute(a.name);});return doc.body.innerHTML;}
const icons={arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',book:'<path d="M12 5v15M3 4c4-1 6 0 9 2 3-2 5-3 9-2v14c-4-1-6 0-9 2-3-2-5-3-9-2Z"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3Zm6-3v15m6-12v15"/>',bag:'<path d="M5 8h14l2 12H3Zm3 0V6a4 4 0 0 1 8 0v2M9 13h6"/>',chart:'<path d="M4 20V4m0 16h16M8 16v-5m5 5V7m5 9V4"/>',settings:'<path d="M4 7h16M4 17h16M8 4v6m8 4v6"/>',check:'<path d="m5 12 4 4 10-10"/>',lens:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',sound:'<path d="m3 9 4 0 5-4v14l-5-4H3Zm13-2c4 3 4 7 0 10m-1-7c1 1 1 3 0 4"/>'};
const icon=(k='spark')=>`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.spark}</svg>`;
const btn=(label,act,cls='btn-primary',attrs='')=>`<button class="btn ${cls}" data-act="${act}" ${attrs}>${label}</button>`;
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch{toast('Opslaan in deze browser is niet beschikbaar. Exporteer je voortgang via Instellingen.');}}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');$('#announcements').textContent=text;toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function chime(){if(state.muted)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();[392,494,587].forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,audioContext.currentTime+i*.12);g.gain.linearRampToValueAtTime(.05,audioContext.currentTime+i*.12+.02);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+i*.12+.55);o.connect(g).connect(audioContext.destination);o.start(audioContext.currentTime+i*.12);o.stop(audioContext.currentTime+i*.12+.6);});}catch{}}
function header(){const r=rank(state);return `<header class="topbar"><button class="brand" data-act="home" aria-label="Onder de oppervlakte, start"><span class="brand-mark">O</span><span><span class="brand-name">Onder de oppervlakte</span><small>Business Ethics · een leeravontuur</small></span></button><nav aria-label="Hoofdnavigatie"><button class="nav-link" data-act="atlas">${icon('map')}<span class="nav-label">Atlas</span></button><button class="nav-link" data-act="inventory">${icon('bag')}<span class="nav-label">Collectie</span></button><button class="nav-link" data-act="library">${icon('book')}<span class="nav-label">Kennis</span></button><button class="nav-link" data-act="progress">${icon('chart')}<span class="nav-label">Mijn groei</span></button><div class="level" aria-label="Level ${r.level}, ${earnedXP(state)} ervaringspunten"><div class="level-badge"><span>${r.level}</span></div><div><strong>${r.title}</strong><small>${earnedXP(state)} XP</small><div class="xp-track"><i style="width:${r.progress/4}%"></i></div></div></div></nav></header>`;}
function render(){app.innerHTML=header()+(state.started?game():landing());}
function landing(){return `<main class="hero" id="main"><div class="hero-art" role="img" aria-label="Een sfeervolle showroom voor repareerbare elektronica"></div><div class="hero-copy"><p class="eyebrow">NOVA · Het tweede leven</p><h1>Onder de<br><em>oppervlakte.</em></h1><p class="lead">Een nieuwe telefoon. Een mooie belofte.<br>Maar wie betaalt de echte prijs?</p><p class="lead">Ontdek hoe economie, mensen, macht en technologie elkaar vormen. Leer de theorie, verzamel inzichten en verander het verhaal.</p><div class="hero-actions">${btn((state.done.length?'Verder met mijn onderzoek':'Begin je onderzoek')+' '+icon('arrow'),'begin')}${btn('Ontdek de vijf hoofdstukken','atlas','btn-quiet')}</div><div class="intro-meta"><span>${icon('book')} Geen voorkennis nodig</span><span>${icon('bag')} 5 hoofdstukken · 29 onderzoeken</span></div></div><div class="hero-foot"><div><p>Jouw keuzes. Nieuwe perspectieven.</p><p>De volledige Business Ethics-leerroute.</p></div><div><div class="chapter-teasers" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span></div><p class="image-caption" style="margin-top:12px">01 / 05 · De belofte</p></div></div></main>`;}
function currentInv(ch=campaign.chapters[state.chapter]){return ch.investigations.find(i=>!state.done.includes(i.id))||ch.investigations.at(-1);}
function game(){const ch=campaign.chapters[state.chapter],inv=currentInv(ch),done=chapterDone(state,ch),count=ch.investigations.filter(i=>state.done.includes(i.id)).length;
return `<main id="main" class="game-layout"><div class="scene-header"><div><p class="eyebrow">Hoofdstuk 0${state.chapter+1} · ${esc(ch.title)}</p><h2>${esc(ch.location)}</h2></div><div class="chapter-steps" aria-label="Hoofdstukken">${campaign.chapters.map((c,n)=>`<button class="step-dot ${n===state.chapter?'current':chapterDone(state,c)?'finished':''}" data-act="chapter" data-index="${n}" aria-label="Hoofdstuk ${n+1}: ${esc(c.title)}" ${unlocked(state,campaign,n)?'':'disabled'}>${chapterDone(state,c)?'✓':n+1}</button>`).join('')}</div></div><section class="scene" aria-label="Interactieve omgeving: ${esc(ch.location)}"><img class="scene-image" src="assets/chapter-${state.chapter+1}.webp" alt="${esc(ch.location)}: een geïllustreerde omgeving waarin je mensen, bewijs en systemen onderzoekt"><div class="scene-atmosphere"></div><div class="scene-label">${esc(sceneLabels[state.chapter])} · interacteer met de omgeving</div>${[['Onderzoek','lens','investigate'],[`${ch.guide.name} · gesprek`,'people','dialogue'],['Werktafel','settings','simulation'],['Dossier','book','dossier']].map(([label,k,a],n)=>`<button class="hotspot ${n===0?'active':''}" data-act="${a}" style="left:${spots[state.chapter][n][0]}%;top:${spots[state.chapter][n][1]}%"><span class="pin">${icon(k)}</span><span>${esc(label)}</span></button>`).join('')}<div class="scene-bottom"><p>${esc(ch.subtitle||ch.intro)}</p><span class="scene-stamp">Kijk verder. Stel vragen. Leg verbanden.</span></div></section><section class="mission-row" aria-label="Je huidige onderzoek"><div><span class="eyebrow">${done?'Hoofdstuk afgerond':`Onderzoek ${count+1} van ${ch.investigations.length}`}</span><h3 class="mission-title">${esc(done?'Je ziet nu meer dan de belofte.':inv.title)}</h3><p>${esc(done?'Je gereedschapskist groeit. Neem deze inzichten mee naar de volgende omgeving.':inv.mission)}</p><div class="mission-progress" aria-label="${count} van ${ch.investigations.length} onderzoeken afgerond">${ch.investigations.map(i=>`<span class="${state.done.includes(i.id)?'done':''}"></span>`).join('')}</div></div><div class="mission-side">${done&&state.chapter<4?btn('Volgende omgeving '+icon('arrow'),'nextChapter'):done?btn('Mijn einddossier '+icon('arrow'),'final'):btn('Verder onderzoeken '+icon('arrow'),'investigate')}${btn('Leerspoor','route','btn-secondary')}</div></section><footer class="utility-strip"><span>Je voortgang wordt automatisch op dit apparaat bewaard.</span><button data-act="settings">${icon('settings')} Instellingen & bewaren</button></footer></main>`;}
function openPanel(title,body,kicker='NOVA · je onderzoek'){returnFocus=document.activeElement;content.innerHTML=`<header class="panel-head"><div><p class="eyebrow">${esc(kicker)}</p><h2 id="panel-title" tabindex="-1">${esc(title)}</h2></div><button class="close" data-act="close" aria-label="Sluiten">×</button></header><div class="panel-body">${body}</div>`;if(!panel.open)panel.showModal();panel.scrollTop=0;$('#panel-title').focus({preventScroll:true});}
function closePanel(){panel.close();flow=null;if(returnFocus?.isConnected)returnFocus.focus();}
function begin(){state.started=true;save();render();if(!state.orientation)orientation();else startInv();}
function orientation(){openPanel('Je hoeft nog niets te weten.',`<p>Je sluit je aan bij het leerlab van NOVA, een fictieve producent van repareerbare telefoons. De lancering ziet er veelbelovend uit. Jij onderzoekt het hele verhaal.</p><div class="orientation-cards"><article><h3>Ethiek begint bij een vraag.</h3><p>Wie krijgt de voordelen, wie draagt de lasten, en waarom vinden we die verdeling gerechtvaardigd? Een feit vertelt wat er gebeurt. Een waarde vertelt wat we belangrijk vinden.</p></article><article><h3>Een systeem stuurt keuzes.</h3><p>Mensen kiezen binnen regels, gewoonten, technologie en prikkels. Je leert zowel individuele keuzes als die omgeving te onderzoeken. Een stakeholder is iemand die invloed heeft op een keuze, of de gevolgen ervan draagt.</p></article><article><h3>Je leert terwijl je onderzoekt.</h3><p>Elke onderzoekstap geeft eerst uitleg en een voorbeeld. Daarna pas je een inzicht toe en probeer je een nieuwe casus. Je mag oefenen, teruggaan en je antwoord verbeteren. Hulp en de kennisbibliotheek blijven beschikbaar.</p></article></div><p class="muted">Je verzamelt gereedschappen en verdient XP. Een level geeft je voortgang aan; de toepassing in nieuwe situaties laat zien wat je kunt. De NOVA-casus is fictief. De theorie komt uit jouw Business Ethics-cursus.</p><div class="panel-footer"><span class="muted">Een nieuw perspectief · +50 XP</span>${btn('Ik ben klaar om te beginnen '+icon('arrow'),'orientationDone')}</div>`,'Welkom in het leerlab');}
function startInv(id){const ch=campaign.chapters[state.chapter],inv=id?ch.investigations.find(i=>i.id===id):currentInv(ch);if(!inv)return;const first=inv.sourceBlocks.findIndex(b=>!state.read.includes(`${ch.lessonId}:${b}`));flow={ch,inv,phase:!id&&first>0?1:!id&&first===-1&&!state.done.includes(inv.id)?2:0,blockPos:Math.max(0,first)};renderFlow();}
function renderFlow(){if(!flow)return;const {ch,inv,phase}=flow,phases=['De situatie','Leer & ontdek','Pas toe','Nieuwe casus','Verzameld'];let body=`<div class="stepper" aria-label="Stap ${phase+1} van 5">${phases.map((p,n)=>`<span class="${n<phase?'past':n===phase?'current':''}"></span>`).join('')}</div><p class="phase-label">0${phase+1} / 05 · ${phases[phase]}</p>`;
if(phase===0){body+=`<h2>${esc(inv.title)}</h2><p>${esc(inv.briefing)}</p><div class="guide"><div class="initial">${esc(ch.guide.name[0])}</div><div><strong>${esc(ch.guide.name)} · ${esc(ch.guide.role)}</strong><p>${esc(inv.mission)}</p></div></div><div class="dialogue">${(inv.dialogue||[]).map(d=>`<p><strong>${esc(d.speaker)}</strong>${esc(d.text)}</p>`).join('')}</div><div class="panel-footer"><span class="muted">Begin bij het inzicht achter de situatie.</span>${btn('Leer & ontdek '+icon('arrow'),'flowNext')}</div>`;}
if(phase===1){const bidx=inv.sourceBlocks[flow.blockPos],lesson=course.lessons.find(l=>l.id===ch.lessonId),block=lesson.blocks[bidx],key=`${lesson.id}:${bidx}`,pass=!['quiz','match'].includes(block.t)||state.read.includes(key);body+=`<div class="source-navigation"><span>Inzicht ${flow.blockPos+1} van ${inv.sourceBlocks.length}</span><progress value="${flow.blockPos+1}" max="${inv.sourceBlocks.length}"></progress><span>Volledige cursusinhoud</span></div><div class="source-body" data-source-key="${key}">${renderBlock(block,key,true)}</div><p class="source-note">${esc(lesson.title)} · bron: Business Ethics, Fabian Berndsen</p><div class="panel-footer">${btn('← Vorige','sourceBack','btn-secondary')}<span class="muted" style="font-size:.73rem">${pass?'Neem de tijd. Je kunt altijd terug.':'Oefen de vraag om verder te gaan.'}</span>${btn((flow.blockPos===inv.sourceBlocks.length-1?'Naar het voorbeeld':'Volgend inzicht')+' '+icon('arrow'),'sourceNext','btn-primary',pass?'':'disabled')}</div>`;}
if(phase===2){const chosen=state.answers[`${inv.id}:activity`],passed=chosen===inv.activity.best,ready=passed&&experimentReady(ch,inv);body+=`<h2>${esc(inv.activity.prompt)}</h2><div class="worked-example"><h3>Zo kun je redeneren · uitgewerkt voorbeeld</h3><p>${esc(inv.workedExample)}</p></div>${inv.experiment?simMarkup(campaign.chapters.indexOf(ch)):""}<p class="muted">Kies de best onderbouwde aanpak voor deze situatie. Je krijgt uitleg bij elke keuze.</p><div class="choice-list">${inv.activity.options.map((o,n)=>`<button class="choice ${chosen===n?'selected':''} ${passed&&chosen===n?'correct':''}" data-act="activityAnswer" data-index="${n}"><span class="letter">${String.fromCharCode(65+n)}</span><span>${esc(o.text)}</span></button>`).join('')}</div>${chosen!==undefined?`<div class="feedback ${passed?'':'retry'}" aria-live="polite"><h3>${passed?'Je redenering is onderbouwd.':'Onderzoek deze keuze verder.'}</h3><p>${esc(inv.activity.options[chosen]?.feedback)}</p>${passed?`<p>${esc(inv.activity.explanation)}</p>`:''}</div>`:''}<div class="panel-footer">${btn('← Naar de theorie','flowBack','btn-secondary')}${btn('Probeer een nieuwe casus '+icon('arrow'),'flowNext','btn-primary',ready?'':'disabled')}</div>`;}
if(phase===3){const chosen=state.answers[`${inv.id}:transfer`],passed=chosen===inv.transfer.correct;body+=`<h2>Neem het inzicht mee.</h2><p>${esc(inv.transfer.prompt)}</p><div class="choice-list">${inv.transfer.options.map((o,n)=>`<button class="choice ${chosen===n?'selected':''} ${passed&&chosen===n?'correct':''}" data-act="transferAnswer" data-index="${n}"><span class="letter">${String.fromCharCode(65+n)}</span><span>${esc(o)}</span></button>`).join('')}</div>${chosen!==undefined?`<div class="feedback ${passed?'':'retry'}" aria-live="polite"><h3>${passed?'Het inzicht werkt ook hier.':'Kijk opnieuw naar het mechanisme.'}</h3><p>${esc(inv.transfer.feedback)}</p></div>`:''}<label class="note-label" for="reflection">${esc(inv.reflection)}</label><textarea id="reflection" data-note="${inv.id}" placeholder="Leg het in je eigen woorden uit. Je notitie blijft in je dossier.">${esc(state.notes[inv.id]||'')}</textarea><div class="panel-footer">${btn('← Naar de toepassing','flowBack','btn-secondary')}${btn('Voeg toe aan mijn collectie '+icon('bag'),'finishInv','btn-primary',passed?'':'disabled')}</div>`;}
if(phase===4){body+=`<div class="reward"><p class="eyebrow">Nieuw in je gereedschapskist</p><div class="artifact-symbol">${icon('lens')}</div><h2>${esc(inv.artifact.title)}</h2><p>${esc(inv.artifact.description)}</p><div class="reward-xp">Onderzoek afgerond · +100 XP</div><p class="muted">Dit gereedschap reist met je mee. Open je collectie om de uitleg en je eigen notitie terug te vinden.</p>${chapterDone(state,ch)?`<div class="chapter-complete"><h3>Een nieuwe laag wordt zichtbaar.</h3><p>Je hebt alle onderzoeken in dit hoofdstuk afgerond.</p>${state.chapter<4?btn('Ontgrendel de volgende omgeving '+icon('arrow'),'nextChapter'):btn('Stel mijn einddossier samen '+icon('arrow'),'final')}</div>`:btn('Verder onderzoeken '+icon('arrow'),'continueInv')}</div>`;}
openPanel(inv.title,body,`${ch.title} · ${ch.guide.name}`);if(phase===2&&inv.experiment)setupSimulation();}
function renderBlock(b,key,interactive=false){
if(b.t==='text')return `${b.heading?`<h2>${esc(b.heading)}</h2>`:''}${html(b.body||'')}`;
if(b.t==='tabs')return b.items.map(i=>`<article class="concept-card"><h3>${esc(i.title)}</h3>${html(i.body)}</article>`).join('');
if(b.t==='list')return `<${b.ordered?'ol':'ul'}>${b.items.map(i=>`<li>${html(i)}</li>`).join('')}</${b.ordered?'ol':'ul'}>`;
if(b.t==='image')return `<figure><img src="assets/course/${encodeURIComponent(b.src.split('/').at(-1))}" alt="${esc(b.caption||'Illustratie bij de cursus')}" loading="lazy"><figcaption>${esc(b.caption)}</figcaption></figure>`;
if(b.t==='svg')return `<figure><div class="diagram" role="img" aria-label="${esc(b.alt)}">${html(b.svg)}</div><figcaption>${esc(b.caption||b.alt)}</figcaption></figure>`;
if(b.t==='video')return `<h2>${esc(b.title||'Bekijk het perspectief')}</h2><iframe title="${esc(b.title||'Cursusvideo')}" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(b.youtube)}?start=${Number(b.start)||0}" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen loading="lazy"></iframe><p style="margin-top:16px">Bekijk hoe dit perspectief aansluit bij het onderzoek. ${b.start?`De video begint op ${Math.floor(b.start/60)}:${String(b.start%60).padStart(2,'0')}.`:''}</p><a href="https://www.youtube.com/watch?v=${encodeURIComponent(b.youtube)}${b.start?`&t=${Number(b.start)}s`:''}" target="_blank" rel="noopener">Open de video op YouTube ↗</a>`;
if(b.t==='quiz'){const selection=state.answers[`source:${key}`]||[],passed=state.read.includes(key);return `<h2>Controleer je inzicht.</h2>${html(b.question)}${interactive?`<div class="choice-list">${b.options.map((o,n)=>`<button class="choice ${selection.includes(n)?'selected':''} ${passed&&selection.includes(n)?'correct':''}" data-act="sourceAnswer" data-index="${n}"><span class="letter">${b.multi?(selection.includes(n)?'✓':'+'):String.fromCharCode(65+n)}</span><span>${html(o.text)}</span></button>`).join('')}</div>${b.multi?btn('Controleer mijn keuzes','checkSource','btn-secondary'):''}<div id="source-feedback">${passed?`<div class="feedback"><h3>Inzicht bevestigd.</h3>${html(b.feedback)}</div>`:''}</div>`:`<div class="concept-card">${b.options.map(o=>`<p>${o.correct?'✓ ':''}${html(o.text)}</p>`).join('')}<p><strong>Toelichting:</strong> ${html(b.feedback)}</p></div>`}`;}
if(b.t==='match'){const passed=state.read.includes(key),order=b.pairs.map((_,n)=>(n+1)%b.pairs.length);return `<h2>Leg de verbinding.</h2>${html(b.question)}${interactive?`${b.pairs.map((p,n)=>`<label class="match-row"><span>${esc(p.left)}</span><select data-pair="${n}" aria-label="Omschrijving bij ${esc(p.left)}"><option value="">Kies een omschrijving</option>${order.map(j=>`<option value="${j}" ${passed&&n===j?'selected':''}>${esc(b.pairs[j].right)}</option>`).join('')}</select></label>`).join('')}${btn('Controleer de verbindingen','checkMatch','btn-secondary')}<div id="source-feedback">${passed?`<div class="feedback">${html(b.feedback)}</div>`:''}</div>`:b.pairs.map(p=>`<article class="concept-card"><h3>${esc(p.left)}</h3><p>${esc(p.right)}</p></article>`).join('')}`;}
return '';
}
function sourceContext(){const {ch,inv,blockPos}=flow,l=course.lessons.find(l=>l.id===ch.lessonId),idx=inv.sourceBlocks[blockPos];return {b:l.blocks[idx],key:`${l.id}:${idx}`};}
function sourceAnswer(n){const {b,key}=sourceContext(),a=`source:${key}`;if(b.multi){const selected=state.answers[a]||[];state.answers[a]=selected.includes(n)?selected.filter(x=>x!==n):[...selected,n];save();renderFlow();}else{state.answers[a]=[n];checkSource();}}
function checkSource(){const {b,key}=sourceContext(),selected=state.answers[`source:${key}`]||[],correct=b.options.map((o,n)=>o.correct?n:-1).filter(n=>n>=0),pass=selected.length===correct.length&&correct.every(n=>selected.includes(n));if(pass){if(!state.read.includes(key))state.read.push(key);save();renderFlow();}else{save();renderFlow();$('#source-feedback').innerHTML=`<div class="feedback retry" aria-live="polite"><h3>Nog een denkstap.</h3><p>${html(b.feedback)}</p><p>Lees de uitleg en probeer opnieuw.</p></div>`;}}
function checkMatch(){const {b,key}=sourceContext(),pass=b.pairs.every((p,n)=>content.querySelector(`[data-pair="${n}"]`).value===String(n));if(pass){if(!state.read.includes(key))state.read.push(key);save();renderFlow();}else $('#source-feedback').innerHTML=`<div class="feedback retry" aria-live="polite"><h3>Er zijn nog verbindingen die niet kloppen.</h3><p>${html(b.feedback)}</p><p>Gebruik de begrippen uit de uitleg en probeer opnieuw.</p></div>`;}
function sourceNext(){const {b,key}=sourceContext();if(['quiz','match'].includes(b.t)&&!state.read.includes(key))return;if(!state.read.includes(key))state.read.push(key);save();if(flow.blockPos<flow.inv.sourceBlocks.length-1)flow.blockPos++;else flow.phase=2;renderFlow();}
function finishInv(){try{const already=state.done.includes(flow.inv.id);completeInvestigation(state,flow.inv,flow.ch.lessonId);save();flow.phase=4;render();renderFlow();if(!already)chime();}catch(e){toast(e.message);}}
function atlas(){openPanel('Vijf omgevingen. Eén verbonden verhaal.',`<p class="muted">Je begint bij de belofte van een product en eindigt bij de systemen die die belofte mogelijk maken. Elke omgeving bouwt voort op de vorige.</p><div class="atlas-grid">${campaign.chapters.map((ch,n)=>{const u=unlocked(state,campaign,n),count=ch.investigations.filter(i=>state.done.includes(i.id)).length;return `<button class="atlas-card ${n===state.chapter?'current':''}" data-act="chapter" data-index="${n}" ${u?'':'disabled'}><img src="assets/chapter-${n+1}.webp" alt="${esc(ch.location)}" loading="lazy"><div class="atlas-copy"><p class="eyebrow">Hoofdstuk 0${n+1} ${u?'':`· ${icon('lock')}`}</p><h3>${esc(ch.title)}</h3><p>${esc(ch.subtitle)}</p><p>${u?`${count} / ${ch.investigations.length} onderzoeken`:'Ontgrendelt na het vorige hoofdstuk'}</p></div></button>`;}).join('')}</div><p class="source-note">Alle theorie is altijd toegankelijk via Kennis. De atlas volgt je geleidelijke leerroute.</p>`,'Je wereldkaart');}
function chapter(n){if(!unlocked(state,campaign,n))return;state.chapter=n;state.started=true;save();closePanel();render();toast(`${campaign.chapters[n].location} geopend.`);}
function nextChapter(){if(!chapterDone(state,campaign.chapters[state.chapter]))return;if(state.chapter<4){chapter(state.chapter+1);startInv();}}
function route(){const ch=campaign.chapters[state.chapter],next=currentInv(ch);openPanel('Volg je leerspoor.',`<p class="muted">Elke onderzoekstap heeft een situatie, volledige theorie, een uitgewerkt voorbeeld, toepassing en een nieuwe casus.</p><div class="route-list">${ch.investigations.map((i,n)=>{const done=state.done.includes(i.id),available=done||i.id===next.id;return `<button class="route-item ${done?'done':i.id===next.id?'current':''}" data-act="investigate" data-id="${i.id}" ${available?'':'disabled'}><span class="route-number">${done?'✓':n+1}</span><span class="route-copy"><strong>${esc(i.title)}</strong><small>${done?'Afgerond · opnieuw bekijken':available?'Jouw volgende onderzoek':'Bouwt voort op de vorige stap'}</small></span>${icon(done?'check':available?'arrow':'lock')}</button>`;}).join('')}</div>`,'Hoofdstuk '+(state.chapter+1));}
function inventory(){const arts=campaign.chapters.flatMap(ch=>ch.investigations.map(i=>({...i.artifact,inv:i,chapter:ch}))),collected=arts.filter(a=>state.artifacts.includes(a.id));openPanel('Je gereedschapskist.',`<p>Inzichten worden gereedschappen die je opnieuw kunt gebruiken. Je hebt <strong>${collected.length} van ${arts.length}</strong> artifacts verzameld.</p>${collected.length?`<div class="collection-grid">${collected.map(a=>`<article class="artifact-card"><p class="eyebrow">${icon('lens')} ${esc(a.chapter.title)}</p><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><label class="note-label" for="note-${esc(a.id)}">Mijn eigen inzicht</label><textarea id="note-${esc(a.id)}" data-note="${a.inv.id}" placeholder="Schrijf hoe je dit gereedschap kunt gebruiken.">${esc(state.notes[a.inv.id]||'')}</textarea>${btn('Uitleg opnieuw bekijken','reviewArtifact','btn-quiet',`data-chapter="${campaign.chapters.indexOf(a.chapter)}" data-id="${a.inv.id}"`)}</article>`).join('')}</div>`:`<div class="worked-example"><h3>Je eerste ontdekking wacht.</h3><p>Rond je eerste onderzoek af om een gereedschap te verzamelen. Je krijgt de uitleg en een plek voor je eigen notities erbij.</p>${btn('Naar mijn onderzoek','continueInv')}</div>`}<p class="source-note">Hulp en theorie zijn ook beschikbaar voordat je een artifact verdient.</p>`,'Collectie · blijft bij je');}
function progress(){const total=campaign.chapters.reduce((a,c)=>a+c.investigations.length,0),r=rank(state);openPanel('Je blik wordt scherper.',`<p>Je level laat je voortgang zien. De nieuwe casussen oefenen of je een inzicht ook in een andere situatie kunt toepassen.</p><div class="stats-grid"><div class="stat"><strong>${r.level}</strong><small>Level · ${r.title}</small></div><div class="stat"><strong>${earnedXP(state)}</strong><small>Verdiende XP</small></div><div class="stat"><strong>${state.done.length}/${total}</strong><small>Onderzoeken afgerond</small></div></div>${campaign.chapters.map((ch,n)=>{const d=ch.investigations.filter(i=>state.done.includes(i.id)).length;return `<div class="skill-row"><div class="skill-label"><span>${esc(['Kosten & waarden zichtbaar maken','Menselijk gedrag in context begrijpen','Macht & zeggenschap analyseren','Technologische keuzes onderzoeken','Claims & praktijk verbinden'][n])}</span><span>${d} / ${ch.investigations.length}</span></div><progress value="${d}" max="${ch.investigations.length}"></progress></div>`;}).join('')}<p class="source-note">Afronding betekent dat je de inhoud hebt doorlopen en de oefeningen hebt opgelost. Of je kennis ook op langere termijn beklijft, oefen je door later nieuwe casussen te bekijken.</p>${state.done.length===total?btn('Open mijn einddossier','final'):''}`,'Mijn groei');}
function library(){openPanel('De kennis achter je onderzoek.',`<p class="muted">De volledige inhoud van de oorspronkelijke Business Ethics-cursus, inclusief voorbeelden, video’s en oefeningen. Deze bibliotheek is altijd beschikbaar.</p><div class="library"><label class="sr-only" for="knowledge-search">Zoek in de theorie</label><input type="search" id="knowledge-search" placeholder="Zoek een begrip, zoals externaliteiten of macht…" value="${esc(searchQuery)}"><div id="knowledge-results">${libraryResults(searchQuery)}</div></div>`,'Kennisbibliotheek');}
function libraryResults(query){const q=query.toLocaleLowerCase('nl');return course.lessons.map(l=>{const blocks=l.blocks.map((b,n)=>({b,n})).filter(({b})=>b.t!=='continue'&&(!q||JSON.stringify(b).toLocaleLowerCase('nl').includes(q)));if(!blocks.length)return '';return `<details ${q?'open':''}><summary>${esc(l.title)} <small class="muted" style="font-family:inherit;font-size:.7rem">${blocks.length} onderdelen</small></summary>${blocks.map(({b,n})=>`<section class="library-block source-body">${renderBlock(b,`${l.id}:${n}`,false)}</section>`).join('')}</details>`;}).join('')||'<p>Geen resultaten. Probeer een ander begrip.</p>';}
function dialogue(){const ch=campaign.chapters[state.chapter],inv=currentInv(ch);openPanel(`In gesprek met ${ch.guide.name}`,`<div class="guide"><span class="initial">${esc(ch.guide.name[0])}</span><div><strong>${esc(ch.guide.name)} · ${esc(ch.guide.role)}</strong><p>${esc(ch.intro)}</p></div></div><div class="dialogue">${(inv.dialogue||[]).map(d=>`<p><strong>${esc(d.speaker)}</strong>${esc(d.text)}</p>`).join('')}</div><div class="worked-example"><h3>Een eerste handvat</h3><p>${esc(inv.workedExample)}</p></div><div class="panel-footer">${btn('Open de kennisbibliotheek','library','btn-secondary')}${btn('Onderzoek deze situatie '+icon('arrow'),'investigate')}</div>`,'Een ander perspectief');}
function dossier(){startInv();flow.phase=1;renderFlow();}
const simulations=[
{title:'Wie betaalt de rekening?',intro:'Een product kan goedkoop lijken omdat een deel van de kosten ergens anders terechtkomt. Verander wie de afvalkosten draagt en vergelijk de bedrijfsrekening met de totale kosten.',controls:`<label for="units">Productie: <strong id="units-value">100</strong> telefoons</label><input id="units" type="range" min="50" max="500" step="50" value="100"><label for="cost-bearer">Wie betaalt de verwerking van afval?</label><select id="cost-bearer"><option value="community">De omgeving</option><option value="shared">Bedrijf en omgeving, ieder de helft</option><option value="company">Het bedrijf</option></select>`,assumption:'Rekenvoorbeeld: €100 productiekosten en €20 afvalkosten per telefoon. De totale kosten veranderen hier niet; alleen wie ze draagt.'},
{title:'Wat maakt jouw team normaal?',intro:'Een organisatie zegt dat zorgvuldigheid belangrijk is. Wat gebeurt er als de beloning alleen op snelheid is gericht? Onderzoek de combinatie van prestatiedruk en ruimte om zorgen te bespreken.',controls:`<label for="pressure">Gewicht van de snelheidsbonus</label><input id="pressure" type="range" min="0" max="100" value="80"><label for="safety">Ruimte om problemen te bespreken</label><input id="safety" type="range" min="0" max="100" value="25">`,assumption:'Dit is een denkmodel. De schuiven illustreren prikkels en spreekruimte; ze voorspellen geen werkelijk gedrag of kansen.'},
{title:'Wie krijgt een stem?',intro:'De onderneming wil investeren in een reparatienetwerk. Hoe verandert het gesprek als verschillende belanghebbenden formeel kunnen meebeslissen?',controls:`<label for="governance">Samenstelling van de besluitvorming</label><select id="governance"><option value="shareholders">Alleen aandeelhouders</option><option value="workers">Aandeelhouders en werknemers</option><option value="stakeholders">Aandeelhouders, werknemers en andere stakeholders</option></select><label for="horizon">Tijdshorizon</label><select id="horizon"><option value="short">Het volgende kwartaal</option><option value="long">De komende vijf jaar</option></select>`,assumption:'De uitkomsten beschrijven mogelijke aandachtspunten. Meer stemmen garanderen geen rechtvaardige uitkomst; vertegenwoordiging en daadwerkelijke invloed tellen mee.'},
{title:'Welke waarde krijgt voorrang?',intro:'NOVA kan vandaag maar twee apparaten repareren. Een systeem rangschikt de aanvragen. Onderzoek hoe een ontwerpkeuze zichtbaar wordt in de volgorde.',controls:`<label for="profit-weight">Gewicht van commerciële waarde: <strong id="profit-value">70%</strong></label><input id="profit-weight" type="range" min="0" max="100" value="70"><p style="font-size:.76rem">Het overige gewicht gaat naar urgentie en toegankelijkheid.</p>`,assumption:'Fictieve aanvragen krijgen twee scores van 0–100. De prioriteit is het gewogen gemiddelde. Deze illustratie is geen gevalideerd beslismodel.'},
{title:'Hoe groot is de groene claim?',intro:'Een telefoon heeft een gerecyclede behuizing. Wat kun je daaruit concluderen over de hele telefoon? Onderzoek waarom de grens van een meting belangrijk is.',controls:`<label for="recycled">Gerecycled materiaal in de behuizing: <strong id="recycled-value">80%</strong></label><input id="recycled" type="range" min="0" max="100" step="10" value="80"><label for="boundary">Waar gaat je claim over?</label><select id="boundary"><option value="housing">Alleen de behuizing</option><option value="phone">Het hele apparaat</option><option value="lifecycle">De hele levenscyclus</option></select>`,assumption:'Rekenvoorbeeld: de behuizing is 40 gram van een telefoon van 200 gram. Over het overige materiaal, energie, arbeid en einde van de levensduur ontbreken gegevens.'}
];
function experimentReady(ch,inv){return !inv.experiment||(state.experiments[ch.lessonId]&&String(state.notes[`sim-${ch.lessonId}`]||'').trim().length>0);}
function simMarkup(n){const sim=simulations[n],ch=campaign.chapters[n];return `<section class="experiment"><p class="eyebrow">Onderzoek het mechanisme</p><h3>${sim.title}</h3><p>${sim.intro}</p><div class="sim-layout"><div class="sim-controls">${sim.controls}</div><div class="sim-result" id="sim-result" aria-live="polite"></div></div><p class="sim-assumption">${sim.assumption}</p><label class="note-label" for="experiment-note">Verander minstens één instelling. Wat verandert er, en waarom?</label><textarea id="experiment-note" data-note="sim-${ch.lessonId}" placeholder="Beschrijf de verschuiving en verbind die aan een begrip.">${esc(state.notes[`sim-${ch.lessonId}`]||'')}</textarea></section>`;}
function setupSimulation(){content.querySelectorAll('.sim-controls input,.sim-controls select').forEach(e=>{if(state.simValues[e.id]!==undefined)e.value=state.simValues[e.id];});updateSimulation();}
function simulation(){const s=simulations[state.chapter];openPanel(s.title,`<p>${s.intro}</p><div class="worked-example"><h3>Voor je begint</h3><p>Voorspel eerst wat je verwacht. Verander daarna één instelling en leg uit welke waarde of kostenpost zichtbaar wordt.</p></div><div class="sim-layout"><div class="sim-controls">${s.controls}</div><div class="sim-result" id="sim-result" aria-live="polite"></div></div><p class="sim-assumption">${s.assumption}</p><label class="note-label" for="sim-note">Wat veranderde er, en hoe verklaar je dat?</label><textarea id="sim-note" data-note="sim-${campaign.chapters[state.chapter].lessonId}" placeholder="Verbind je observatie aan de theorie.">${esc(state.notes[`sim-${campaign.chapters[state.chapter].lessonId}`]||'')}</textarea><div class="panel-footer">${btn('Bekijk de theorie','library','btn-secondary')}${btn('Terug naar mijn onderzoek','investigate')}</div>`,'Werktafel · verken het systeem');setupSimulation();}
function updateSimulation(){const result=$('#sim-result');if(!result)return;const n=state.chapter;
if(n===0){const units=Number($('#units').value),share={community:0,shared:.5,company:1}[$('#cost-bearer').value],corp=units*(100+20*share),external=units*20*(1-share);$('#units-value').textContent=units;result.innerHTML=`<h3>De rekening van NOVA</h3><div class="sim-metric">€ ${corp.toLocaleString('nl-NL')}</div><div class="bar-row"><span>Bij het bedrijf</span><span class="bar"><i style="width:${corp/(units*120)*100}%"></i></span></div><div class="bar-row"><span>Bij de omgeving</span><span class="bar"><i style="width:${external/(units*120)*100}%;background:#c98c64"></i></span></div><p>De omgeving betaalt <strong>€ ${external.toLocaleString('nl-NL')}</strong>. De totale kosten zijn <strong>€ ${(units*120).toLocaleString('nl-NL')}</strong>.</p><p>${external?'Een deel van de rekening valt buiten de bedrijfsbegroting. Dat is een externaliteit.':'De afvalkosten zijn opgenomen in de bedrijfsrekening: de externaliteit is in dit voorbeeld geïnternaliseerd.'}</p>`;}
if(n===1){const p=Number($('#pressure').value),s=Number($('#safety').value);result.innerHTML=`<h3>De boodschap van het systeem</h3><p><strong>${p>60?'Snelheid weegt zwaar.':p>30?'Meerdere doelen zijn in beeld.':'De snelheidsbonus is beperkt.'}</strong></p><p>${s<35?'Zorgen uitspreken voelt moeilijk. Medewerkers kunnen problemen eerder voor zichzelf houden.':s<70?'Er is enige ruimte om vragen te stellen. Of twijfel gevolgen krijgt, hangt ook af van de reactie van leidinggevenden.':'Er is ruimte voor twijfel, tegenspraak en het bespreken van fouten.'}</p><div class="bar-row"><span>Snelheidsbonus</span><span class="bar"><i style="width:${p}%;background:#c98c64"></i></span></div><div class="bar-row"><span>Spreekruimte</span><span class="bar"><i style="width:${s}%"></i></span></div><p>${p>60&&s<35?'Vraag: wat gebeurt er wanneer iemand zegt “we moeten een kwaliteitsprobleem onderzoeken”?':'Vraag: sluiten de beloning, teamnormen en formele waarden op elkaar aan?'}</p>`;}
if(n===2){const g=$('#governance').value,h=$('#horizon').value;result.innerHTML=`<h3>Wat komt op tafel?</h3><p>${g==='shareholders'?'Rendement, investeringsrisico en kapitaal kunnen de agenda domineren. De gevolgen voor andere groepen moeten bewust worden ingebracht.':g==='workers'?'Naast financiële belangen komen werkdruk, vakkennis en continuïteit directer aan tafel. Wie spreekt voor klanten en de omgeving?':'Meerdere belangen worden formeel zichtbaar. Verschillen in informatie, afhankelijkheid en onderhandelingsmacht blijven bestaan.'}</p><p>${h==='short'?'Een reparatienetwerk kost nu geld; de opbrengst kan later komen. Een korte horizon kan dit minder aantrekkelijk laten lijken.':'Een langere horizon maakt toekomstige reparatie-inkomsten en relaties zichtbaarder. Langetermijndenken neemt belangenconflicten niet weg.'}</p><p><strong>Ontwerpvraag:</strong> wie heeft een stem, wie heeft beslissingsmacht, en wie ontbreekt?</p>`;}
if(n===3){const w=Number($('#profit-weight').value)/100;$('#profit-value').textContent=Math.round(w*100)+'%';const cases=[['Grote zakelijke klant',95,20],['Student met kapotte studietelefoon',35,90],['Bewoner zonder ander digitaal toegangsmiddel',15,100],['Luxe toestel met cosmetische schade',85,10]].map(([name,p,u])=>({name,p,u,score:p*w+u*(1-w)})).sort((a,b)=>b.score-a.score);result.innerHTML=`<h3>De volgorde van vandaag</h3>${cases.map((c,i)=>`<p><strong>${i+1}. ${c.name}</strong><br>Prioriteit ${c.score.toFixed(0)} · commercieel ${c.p}, urgentie ${c.u}</p>`).join('')}<p>De eerste twee aanvragen worden geholpen. De regel lijkt technisch, maar bepaalt welke waarde voorrang krijgt.</p>`;}
if(n===4){const r=Number($('#recycled').value),b=$('#boundary').value;$('#recycled-value').textContent=r+'%';result.innerHTML=`<h3>Wat is onderbouwd?</h3><div class="sim-metric">${b==='housing'?r+'%':b==='phone'?(r*.2).toFixed(0)+'%':'Onvoldoende gegevens'}</div><p>${b==='housing'?`${r}% van de behuizing is gerecycled. Dat is een afgebakende materiaalclaim.`:b==='phone'?`Uit de behuizing volgt slechts ${(r*.2).toFixed(0)}% gerecycled materiaal voor het totale apparaatgewicht. Over het overige materiaal weten we niets.`:'Een materiaalpercentage zegt onvoldoende over energie, productie, arbeid, gebruik en afval. “100% duurzaam” volgt niet uit deze meting.'}</p><p><strong>Controleer:</strong> definitie, meetgrens, bewijs en de informatie die ontbreekt.</p>`;}}
function finalDossier(){const all=campaign.chapters.every(ch=>chapterDone(state,ch));openPanel(all?'Van inzicht naar interventie.':'Je einddossier groeit.',`<h2>${all?'Je hebt het hele verhaal onderzocht.':'Welke verandering zou jij voorstellen?'}</h2><p>Verbind de vijf perspectieven in één voorstel voor NOVA. Beschrijf wie de gevolgen draagt, hoe gedrag wordt gestuurd, waar de macht zit, welke technologische keuze ertoe doet en hoe een claim controleerbaar wordt.</p><div class="orientation-cards">${['Welke kosten en belangen vallen nu buiten beeld?','Welke prikkels en groepsnormen houden het probleem in stand?','Wie kan de regels veranderen, en wie krijgt een stem?','Wat moet er veranderen aan technologie of infrastructuur?','Welk bewijs heb je nodig om de verbetering te onderbouwen?'].map((t,n)=>`<article><h3>0${n+1} · ${t}</h3><textarea data-note="final-${n}" placeholder="Onderbouw je voorstel met begrippen en bewijs uit je onderzoek.">${esc(state.notes[`final-${n}`]||'')}</textarea></article>`).join('')}</div><p class="muted">Er kunnen meerdere verdedigbare voorstellen zijn. Gebruik een concreet mechanisme, benoem een afweging en geef aan wat je nog moet onderzoeken.</p><div class="panel-footer">${btn('Exporteer mijn dossier','exportDossier','btn-secondary')}${btn(all?'Leerroute afronden':'Terug naar mijn leerspoor',all?'completeCourse':'route')}</div>`,'Het tweede leven · jouw voorstel');}
function settings(){openPanel('Jouw onderzoek bewaren.',`<p>Voortgang en notities blijven in deze browser. Maak een export om op een ander apparaat verder te gaan of je dossier te bewaren.</p><div class="settings-list">${btn(icon('sound')+' Beloningsgeluid: '+(state.muted?'uit':'aan'),'toggleSound','btn-secondary')}${btn('Download voortgang en notities','exportSave','btn-secondary')}<label class="btn btn-secondary" for="import-save">Importeer een opgeslagen voortgang<input id="import-save" type="file" accept="application/json,.json" class="sr-only"></label>${btn('Download mijn leerdossier','exportDossier','btn-secondary')}${btn('Begin een nieuw onderzoek','confirmReset','btn-quiet')}</div><p class="source-note">De NOVA-personen, documenten en werktafels zijn fictieve leersituaties. Alle oorspronkelijke cursusonderdelen zijn opgenomen. De economische modellen in de theorie zijn perspectieven die je kunt onderzoeken en beargumenteren.</p>`,'Instellingen');}
function download(name,type,text){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportDossier(){let text=`ONDER DE OPPERVLAKTE — MIJN BUSINESS ETHICS-DOSSIER\nNOVA · Het tweede leven\n\n${state.done.length} onderzoeken afgerond · ${earnedXP(state)} XP\n\n`;campaign.chapters.forEach(ch=>{text+=`\n${ch.title.toUpperCase()}\n`;ch.investigations.filter(i=>state.done.includes(i.id)).forEach(i=>{text+=`\n${i.artifact.title}\n${i.artifact.description}\nMijn inzicht: ${state.notes[i.id]||'Nog geen notitie.'}\n`;});});text+='\nMIJN INTERVENTIEVOORSTEL\n';for(let n=0;n<5;n++)text+=`\nPerspectief ${n+1}: ${state.notes[`final-${n}`]||'Nog geen notitie.'}\n`;download('mijn-business-ethics-dossier.txt','text/plain;charset=utf-8',text);toast('Je leerdossier is gedownload.');}
const actions={home:()=>{state.started=false;save();render();},begin,close:closePanel,orientationDone:()=>{state.orientation=true;save();render();chime();startInv();},atlas,inventory,library,progress,settings,route,chapter:b=>chapter(Number(b.dataset.index)),nextChapter,investigate:b=>startInv(b.dataset.id),continueInv:()=>{if(!state.started){begin();return;}startInv();},dialogue,dossier,simulation,flowNext:()=>{if(flow.phase===2&&(state.answers[`${flow.inv.id}:activity`]!==flow.inv.activity.best||!experimentReady(flow.ch,flow.inv)))return;flow.phase++;renderFlow();},flowBack:()=>{flow.phase=Math.max(0,flow.phase-1);renderFlow();},sourceNext,sourceBack:()=>{if(flow.blockPos>0)flow.blockPos--;else flow.phase=0;renderFlow();},sourceAnswer:b=>sourceAnswer(Number(b.dataset.index)),checkSource,checkMatch,activityAnswer:b=>{state.answers[`${flow.inv.id}:activity`]=Number(b.dataset.index);save();renderFlow();},transferAnswer:b=>{state.answers[`${flow.inv.id}:transfer`]=Number(b.dataset.index);save();renderFlow();},finishInv,reviewArtifact:b=>{state.chapter=Number(b.dataset.chapter);save();render();startInv(b.dataset.id);flow.phase=1;renderFlow();},final:finalDossier,completeCourse:()=>{if(!campaign.chapters.every(ch=>chapterDone(state,ch)))return;state.finish=true;save();chime();openPanel('Je leerroute is afgerond.',`<div class="reward"><div class="artifact-symbol">${icon('spark')}</div><h2>Je kijkt nu onder de oppervlakte.</h2><p>Je hebt alle vijf hoofdstukken, de volledige cursusinhoud en 29 onderzoeken doorlopen. Je collectie en dossier blijven beschikbaar.</p><p class="muted">Kom later terug om een casus opnieuw te onderzoeken. Een inzicht wordt sterker wanneer je het opnieuw gebruikt.</p><div class="reward-xp">${earnedXP(state)} XP · ${rank(state).title}</div>${btn('Download mijn dossier','exportDossier')}${btn('Bekijk mijn groei','progress','btn-quiet')}</div>`,'Business Ethics · complete leerroute');},toggleSound:()=>{state.muted=!state.muted;save();if(!state.muted)chime();settings();},exportSave:()=>{download('onder-de-oppervlakte-voortgang.json','application/json',JSON.stringify(state,null,2));toast('Je voortgang is gedownload.');},exportDossier,confirmReset:()=>openPanel('Een nieuw onderzoek beginnen?',`<p>Hiermee wis je de voortgang en notities op dit apparaat. Download eerst een export als je dit onderzoek wilt bewaren.</p><div class="panel-footer">${btn('Terug','settings','btn-secondary')}${btn('Wis en begin opnieuw','reset')}</div>`,'Voortgang'),reset:()=>{state=newState();save();closePanel();render();toast('Je kunt opnieuw beginnen.');}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b&&!b.disabled){const fn=actions[b.dataset.act];if(fn)fn(b);}});
document.addEventListener('input',e=>{if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;save();const next=content.querySelector('[data-act=flowNext]');if(next&&flow?.phase===2)next.disabled=state.answers[`${flow.inv.id}:activity`]!==flow.inv.activity.best||!experimentReady(flow.ch,flow.inv);}if(e.target.id==='knowledge-search'){searchQuery=e.target.value;$('#knowledge-results').innerHTML=libraryResults(searchQuery);}if(e.target.closest('.sim-controls')){state.simValues[e.target.id]=e.target.value;state.experiments[campaign.chapters[state.chapter].lessonId]=true;save();updateSimulation();}});
document.addEventListener('change',async e=>{if(e.target.closest('.sim-controls')){state.simValues[e.target.id]=e.target.value;state.experiments[campaign.chapters[state.chapter].lessonId]=true;save();updateSimulation();}if(e.target.id==='import-save'){try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.done))throw Error();state=normaliseState(data,campaign);save();closePanel();render();toast('Je opgeslagen onderzoek is geopend.');}catch{toast('Dit bestand is geen geldige voortgangsexport.');}}});
panel.addEventListener('click',e=>{if(e.target===panel){const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});
panel.addEventListener('cancel',()=>{flow=null;});
try{const responses=await Promise.all([fetch('course.json'),fetch('campaign.json')]);if(responses.some(r=>!r.ok))throw Error('De leerinhoud kon niet worden geladen.');[course,campaign]=await Promise.all(responses.map(r=>r.json()));let stored;try{stored=JSON.parse(localStorage.getItem(SAVE_KEY));}catch{}state=normaliseState(stored,campaign);if(!unlocked(state,campaign,state.chapter))state.chapter=0;render();}catch(e){app.innerHTML=`<main id="main" class="loading"><h2>De wereld is nog niet geladen.</h2><p>${esc(e.message)}</p><p>Vernieuw de pagina om opnieuw te proberen.</p><button class="btn btn-primary" onclick="location.reload()">Opnieuw laden</button></main>`;}
